def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]
    opD = op.count('D')
    opC = n - opD
    myD = me.count('D')

    # Near end, exploit cooperators and defect if opponent is aggressive.
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 4:
        if opD == 0:
            return 'D'
        if opC * 2 >= n:
            return 'C' if op[-1] == 'C' else 'D'
        return 'D'

    # Immediate forgiveness to break mutual defection deadlocks.
    if n >= 3 and me[-1] == 'D' and op[-1] == 'D':
        if op[-2] == 'D' and me[-2] == 'D':
            return 'C'
        if rng.random() < 0.35:
            return 'C'

    # If opponent just cooperated after our defection, reward strongly.
    if op[-1] == 'C' and me[-1] == 'D':
        return 'C'

    # Detect persistent heavy defectors.
    look = min(n, 16)
    recentD = 0
    for i in range(n - look, n):
        if op[i] == 'D':
            recentD += 1
    ratio = recentD / look

    if opD == 0:
        # Occasionally probe a pure cooperator but not enough to break trust.
        if n >= 12 and rng.random() < 0.04:
            return 'D'
        return 'C'

    if ratio <= 0.2:
        # Mostly cooperative: preserve cooperation, forgive isolated D.
        if op[-1] == 'C':
            return 'C'
        # Opponent just defected but rarely defected overall - retaliate briefly.
        return 'D' if rng.random() < 0.6 else 'C'

    if ratio >= 0.7:
        # Heavy defector: defect, but probe occasionally.
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Moderate opponent: tit-for-tat with short memory and forgiveness.
    if op[-1] == 'D':
        if opD >= 3 and op[-2] == 'D' and op[-3] == 'D':
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated: check if we've been exploited too much.
    if n >= 8 and myD > opD + 2:
        return 'D' if rng.random() < 0.4 else 'C'

    return 'C'
